// Hand-transcribed ground truth for the photos in test/fixtures/vision/*.json
// (captured with scripts/capture-vision-fixtures.ts). Values are what the
// receipt *printed*, not handwritten corrections next to them — quantity is
// the printed Qty even where staff crossed it out or wrote a different count.
//
// Each page is self-checked in receipt-parser.test.ts: every row satisfies
// Qty × Unit/Box × Price = Total, and the rows add up to the page's printed
// footer (Total Pcs / Total Box / Total Item/s / Total Value) — so a
// transcription slip fails loudly instead of skewing the accuracy numbers.

export type Row = [
  item_code: string,
  item_name: string,
  unit_count: number,
  unit: "BOX" | "PIECE",
  quantity: number,
  item_price: number,
  total_item_price: number,
];

export interface ExpectedPage {
  // A header field that isn't legible on the photo at all (folded under,
  // cut off) is null and not scored.
  header: {
    delivery_code: string;
    warehouse_code: string;
    delivery_date: string | null;
    receipt_store_code: string | null;
    printout_datetime: string;
  };
  // The printed totals block under the table; null when the page has none
  // (a middle page of a long receipt).
  footer: { total_pcs: number | null; total_box: number; total_items: number; total_value: number } | null;
  items: Row[];
}

